try {
  const req = $input.first().json || {};
  const body = (req.body && typeof req.body === 'object') ? req.body : {};
  const headers = req.headers || {};
  const secret = String($env.WEBHOOK_SHARED_SECRET || '').trim();
  if (secret && String(headers['x-webhook-secret'] || '') !== secret) {
    return [{ json: { ok: false, httpStatus: 401, responseBody: { error: 'unauthorized' } } }];
  }
  const clean = (v) => {
    if (typeof v === 'string') return v.trim();
    if (typeof v === 'number' && Number.isFinite(v)) return String(v);
    return '';
  };
  const LIMITS = { name: 200, email: 254, phone: 50, message: 5000, property_type: 200, preferred_location: 200, budget: 200, timeline: 200 };
  const REQUIRED = ['name', 'email', 'phone', 'message'];
  const OPTIONAL = ['property_type', 'preferred_location', 'budget', 'timeline'];
  const lead = {};
  const missing = [];
  for (const k of REQUIRED) {
    const v = clean(body[k]);
    if (v) { lead[k] = v.slice(0, LIMITS[k]); } else { missing.push(k); }
  }
  for (const k of OPTIONAL) {
    const v = clean(body[k]);
    if (v) { lead[k] = v.slice(0, LIMITS[k]); }
  }
  if (missing.length) {
    return [{ json: { ok: false, httpStatus: 400, responseBody: { error: 'invalid_lead', missing } } }];
  }
  return [{ json: { ok: true, lead } }];
} catch (e) {
  return [{ json: { ok: false, httpStatus: 500, responseBody: { error: 'workflow_error' } } }];
}

const uuid = () => {
  if (typeof crypto !== 'undefined' && crypto && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : ((r & 0x3) | 0x8)).toString(16);
  });
};
const lead = $input.first().json.lead;
return [{ json: { id: uuid(), lead, attempt: 1, maxAttempts: 3 } }];

const state = $('Prepare Attempt').item.json;
const r = $input.item.json || {};
const statusCode = Number.isInteger(r.statusCode) ? r.statusCode : null;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
if (!body || typeof body !== 'object') { body = null; }

const networkError = statusCode === null;
const hasReport = body !== null && typeof body.status === 'string' && Array.isArray(body.steps);
const retryObj = (hasReport && body.retry && typeof body.retry === 'object') ? body.retry : {};
const retryRecommended = hasReport && retryObj.recommended === true;
const retrySteps = Array.isArray(retryObj.steps) ? retryObj.steps.map(String) : [];
const repairs = (hasReport && Array.isArray(body.repair)) ? body.repair : [];
const steps = hasReport ? body.steps.filter((x) => x && typeof x === 'object') : [];
const failedSteps = steps.filter((x) => x.status === 'failed').map((x) => ({
  name: String(x.name || '?'),
  reason: String(x.reason || '?'),
  category: (x.error && x.error.category) ? String(x.error.category) : String(x.reason || '?'),
  retryable: x.retryable === true,
  message: (x.error && x.error.message) ? String(x.error.message).slice(0, 200) : '',
}));
const stepSummary = steps.map((x) => ({ name: String(x.name || '?'), status: String(x.status || '?'), reason: String(x.reason || '?') }));
const dryRun = steps.some((x) => x.reason === 'dry_run');
const category = (hasReport && typeof body.category === 'string') ? body.category : null;
const score = (hasReport && Number.isInteger(body.score)) ? body.score : null;
const pipelineStatus = hasReport ? body.status : null;
const canRetry = state.attempt < state.maxAttempts;

let decision;
let reason;
if (networkError) {
  decision = canRetry ? 'retry' : 'terminal_failure';
  reason = canRetry ? 'network_error' : 'retries_exhausted';
} else if (!hasReport) {
  const transientHttp = [429, 502, 503, 504].includes(statusCode);
  decision = (transientHttp && canRetry) ? 'retry' : 'terminal_failure';
  reason = transientHttp ? (canRetry ? 'upstream_unavailable' : 'retries_exhausted') : ('http_' + statusCode);
} else if (repairs.length > 0) {
  decision = 'repair';
  reason = 'flag_repair_needed';
} else if (retryRecommended && canRetry) {
  decision = 'retry';
  reason = 'retryable_steps';
} else if (pipelineStatus === 'completed') {
  decision = ['hot', 'warm'].includes(category) ? 'notify_success' : 'quiet_success';
  reason = 'completed';
} else {
  decision = 'terminal_failure';
  reason = (retryRecommended && !canRetry) ? 'retries_exhausted' : (pipelineStatus === 'failed' ? 'pipeline_failed' : 'partial_not_retryable');
}

return { json: {
  id: state.id, lead: state.lead, attempt: state.attempt, maxAttempts: state.maxAttempts,
  httpStatus: statusCode, networkError, hasReport, pipelineStatus, category, score,
  retryRecommended, retrySteps, repairs, failedSteps, steps: stepSummary, dryRun, canRetry,
  decision, reason,
} };

const s = $input.first().json;
const FLAGS = ['email_sent', 'sms_sent', 'hubspot_created'];
const expectedAction = 'PATCH /leads/' + s.id + '/flags';
const out = [];
for (const r of (s.repairs || [])) {
  const raw = (r && r.body && typeof r.body === 'object') ? r.body : {};
  const patchBody = {};
  for (const f of FLAGS) { if (raw[f] === true) { patchBody[f] = true; } }
  const valid = !!r && r.action === expectedAction && Object.keys(patchBody).length > 0;
  out.push({ json: { state: s, patchUrlPath: '/leads/' + s.id + '/flags', patchBody: valid ? patchBody : {} } });
}
if (out.length === 0) {
  out.push({ json: { state: s, patchUrlPath: '/leads/' + s.id + '/flags', patchBody: {} } });
}
return out;

const state = $('Build Repairs').first().json.state;
const results = $input.all().map((i) => i.json || {});
const okAll = results.length > 0 && results.every((x) => Number.isInteger(x.statusCode) && x.statusCode >= 200 && x.statusCode < 300);
const remaining = (state.failedSteps || []).filter((f) => f.reason !== 'flag_update_failed');
let decision;
let reason;
if (!okAll) {
  decision = 'terminal_failure';
  reason = 'repair_failed';
} else if (remaining.length === 0) {
  decision = ['hot', 'warm'].includes(state.category) ? 'notify_success' : 'quiet_success';
  reason = 'repaired';
} else if (state.retryRecommended && state.canRetry) {
  decision = 'retry';
  reason = 'retryable_steps_after_repair';
} else {
  decision = 'terminal_failure';
  reason = state.retryRecommended ? 'retries_exhausted' : 'partial_not_retryable';
}
return [{ json: Object.assign({}, state, { decision, reason, repairedOk: okAll }) }];

const s = $input.item.json;
const base = s.networkError ? 120 : 60;
const waitSeconds = base * Math.pow(2, Math.max(0, s.attempt - 1));
return { json: { id: s.id, lead: s.lead, attempt: s.attempt + 1, maxAttempts: s.maxAttempts, waitSeconds } };

const s = $input.item.json;
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const l = s.lead || {};
const pick = (label, v) => (v ? label + ': ' + esc(String(v).slice(0, 80)) : null);
const attrs = [pick('Property', l.property_type), pick('Location', l.preferred_location), pick('Budget', l.budget), pick('Timeline', l.timeline)].filter(Boolean).join(' | ');
const icon = s.category === 'hot' ? ':fire:' : ':sunny:';
const outbound = (s.steps || []).filter((x) => ['email', 'sms', 'crm'].includes(x.name)).map((x) => x.name + ': ' + (x.reason === 'flag_update_failed' ? 'sent (flag repaired)' : esc(x.reason))).join(' | ');
const lines = [
  icon + ' *' + esc(String(s.category).toUpperCase()) + ' lead* - score ' + esc(s.score) + (s.dryRun ? ' _[DRY RUN: nothing was sent]_' : '') + (s.reason === 'repaired' ? ' _(flag repaired automatically)_' : ''),
  attrs || '_no property details provided_',
  'Steps: ' + outbound,
  'Lead ID: ' + esc(s.id),
];
return { json: { slackPayload: { text: lines.join('\n') } } };

const s = $input.item.json;
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const reasons = {
  repair_failed: 'Automatic flag repair failed. A message was already sent, so do NOT re-run the pipeline; patch the flags manually.',
  retries_exhausted: 'Retries exhausted. Re-sending the same request (same id) is safe.',
  partial_not_retryable: 'A step failed with a non-retryable error. Fix the cause, then re-send the same request (same id).',
  pipeline_failed: 'The pipeline failed before the lead was stored.',
  http_422: 'The backend rejected the lead as invalid (HTTP 422). Check the submitted lead data; re-sending it unchanged will fail again.',
};
const failed = (s.failedSteps || []).map((f) => '- ' + esc(f.name) + ': ' + esc(f.category) + (f.retryable ? ' (retryable)' : '') + (f.message ? ' - ' + esc(f.message) : ''));
const fixes = (s.reason === 'repair_failed' ? (s.repairs || []) : []).map((r) => '  PATCH /leads/' + esc(s.id) + '/flags ' + esc(JSON.stringify((r && r.body) ? r.body : {})));
const base = String($env.N8N_EDITOR_BASE_URL || '').replace(/\/+$/, '');
const link = base ? (base + '/workflow/' + $workflow.id + '/executions/' + $execution.id) : '';
const lines = [
  ':rotating_light: *Lead pipeline needs attention*',
  'Lead ID: ' + esc(s.id) + ' | Attempt ' + s.attempt + '/' + s.maxAttempts + ' | HTTP ' + ((s.httpStatus === null || s.httpStatus === undefined) ? 'no response' : s.httpStatus),
  'Reason: ' + esc(reasons[s.reason] || (String(s.reason).indexOf('http_') === 0 ? ('The backend returned HTTP ' + String(s.reason).slice(5) + ' without a pipeline report. Check the backend logs.') : s.reason)),
];
if (failed.length) { lines.push('Failed steps:\n' + failed.join('\n')); }
if (fixes.length) { lines.push('Manual fix:\n' + fixes.join('\n')); }
if (link) { lines.push('n8n execution: ' + link); }
return { json: { slackPayload: { text: lines.join('\n') } } };
